/*===========================================================================

FUNCTION          RRCCSP_SEND_LTE_INTERRAT_REDIRECTION_REQ

DESCRIPTION       This function is responsible for sending
                  LTE_RRC_TDSCDMA_REDIR_REQ to LTE-RRC.

DEPENDENCIES
                  None.

RETURN VALUE
                  None.

SIDE EFFECTS      None.
===========================================================================*/
static void tdsrrccsp_send_lte_interrat_redirection_req
(
  void
)
{
  tdsrrc_SysInfoType19 *sib19_ptr = NULL;
  lte_rrc_tdscdma_redir_req_s lte_interrat_redir_req;
  tdsrrclog_tdscdma_to_lte_redir_start_event_type td2l_redir_event;

  memset(&lte_interrat_redir_req,0,sizeof(lte_rrc_tdscdma_redir_req_s));
  memset(&td2l_redir_event,0,sizeof(tdsrrclog_tdscdma_to_lte_redir_start_event_type));

  lte_interrat_redir_req.irat_nas_info.network_select_mode = tdsrrc_csp_int_data.network_select_mode;
  lte_interrat_redir_req.irat_nas_info.req_plmn = 
    mmumts_convert_rrc_plmn_id_to_nas_plmn_id(tdsrrc_csp_int_data.curr_req_plmn.plmn_id);
  lte_interrat_redir_req.irat_nas_info.rat_pri_list = tdsrrc_csp_int_data.rat_pri_list_info;

  memset(&lte_interrat_redir_req.dedicated_priority_info,0,sizeof(lte_irat_dedicated_priority_info_s));
#ifdef FEATURE_TDSCDMA_ABSOLUTE_PRIORITY
  tdsrrcmeas_populate_dedicated_priority_info_for_irat_req(&lte_interrat_redir_req.dedicated_priority_info);
#endif

  lte_interrat_redir_req.redir_earfcn_list = tdsrrc_csp_int_data.saved_rrc_cmd.cmd.redirect_req.u.EUTRA_target_cell_info;

  if(tdsrrc_csp_int_data.saved_rrc_cmd.cmd.redirect_req.proc_id == TDSRRC_PROCEDURE_RCR)
  {
    lte_interrat_redir_req.cause = LTE_RRC_IRAT_TDSCDMA_REDIR_CAUSE_CONN_RELEASE;
    lte_interrat_redir_req.t_wait_time_ms = 10*1000;

      /* Also update CCM with cell loss for redirection via conn release msg. This is required for the scenario
         where buffered EST_REQ has to be handled after resume failure. This chnage will make sure that RCE waits for
         UE to camp while CSP preforms ACQ-DB search after resume failure. */
    tdsrrcccm_update_with_cell_loss();
  }
  else if(tdsrrc_csp_int_data.saved_rrc_cmd.cmd.redirect_req.proc_id == TDSRRC_PROCEDURE_RCE)
  {
    lte_interrat_redir_req.cause = LTE_RRC_IRAT_TDSCDMA_REDIR_CAUSE_CONN_REJECT;
    lte_interrat_redir_req.t_wait_time_ms = tdsrrc_csp_int_data.saved_rrc_cmd.cmd.redirect_req.wait_time * 1000;
  }
  else
  {
    TDSRRC_MSG0(MSG_LEGACY_ERROR,"Invalid procedure ID");
    return;    
  }

  /* Send LTE neighbour EARFCN's from SIB19 to optimize search on LTE */
  lte_interrat_redir_req.nbr_earfcn_list.earfcn_count = 0;
#ifdef FEATURE_TDSCDMA_SIB19
  sib19_ptr = (tdsrrc_SysInfoType19 *)tdsrrcsibdb_return_sib_for_srv_cell(tdsrrc_SIB19);
#endif
  if(sib19_ptr == NULL)
  {
    TDSRRC_MSG0(MSG_LEGACY_HIGH,"TD2L: SIB19 is NULL. No neighbour cell freqs added to redirection req.");
  }
  else
  {
    if(sib19_ptr->m.eutra_FrequencyAndPriorityInfoListPresent)
    {
      tdsrrc_EUTRA_FrequencyAndPriorityInfoList *eutra_freq_pri_list_ptr = &sib19_ptr->eutra_FrequencyAndPriorityInfoList;
      uint8 num_eutra_freqs = 0;
      uint32 idx = 0;
  
      while((eutra_freq_pri_list_ptr->n > idx) && (num_eutra_freqs < LTE_RRC_IRAT_MAX_NBR_FREQ))
      {
        lte_interrat_redir_req.nbr_earfcn_list.earfcn[num_eutra_freqs++] = (lte_earfcn_t)eutra_freq_pri_list_ptr->elem[idx].earfcn;/*FR17879*/
        idx++;
      }
      lte_interrat_redir_req.nbr_earfcn_list.earfcn_count = num_eutra_freqs;
    }
  }

  /*Send the message to MSGR*/
  /*LTE_RRC_TDSCDMA_REDIRL_REQ*/
  msgr_init_hdr(&lte_interrat_redir_req.msg_hdr,MSGR_TDSCDMA_RRC,LTE_RRC_TDSCDMA_REDIR_REQ);
#ifdef FEATURE_DUAL_SIM
#ifdef FEATURE_TDSCDMA_MSIM_L_PLUS_L
  msgr_set_hdr_variant(&lte_interrat_redir_req.msg_hdr, (uint8)tdsrrc_get_as_id());
#else
  msgr_set_hdr_inst(&lte_interrat_redir_req.msg_hdr, SYS_AS_ID_TO_INST_ID(tdsrrc_get_as_id()));
#endif
#endif
  msgr_send(&lte_interrat_redir_req.msg_hdr, sizeof(lte_rrc_tdscdma_redir_req_s));

  if(TDSCHECK_OPTIONAL_FEATURE_CFA_SUPPORTED)
  {
    tdscfa_send_message_to_lte_rrc(&lte_interrat_redir_req.msg_hdr, sizeof(lte_rrc_tdscdma_redir_req_s));
  }

  TDSRRC_MSG0(MSG_LEGACY_HIGH,"TD2L: LTE_RRC_TDSCDMA_REDIR_REQ sent to LTE RRC");

  td2l_redir_event.redir_cause = TDTOL_REDIR_NONE;
  if(lte_interrat_redir_req.cause == LTE_RRC_IRAT_TDSCDMA_REDIR_CAUSE_CONN_RELEASE)
  {
    td2l_redir_event.redir_cause = TDTOL_REDIR_CONN_RELEASE;
  }
  else if (lte_interrat_redir_req.cause == LTE_RRC_IRAT_TDSCDMA_REDIR_CAUSE_CONN_REJECT)
  {
    td2l_redir_event.redir_cause = TDTOL_REDIR_CONN_REJECT;
  }
  td2l_redir_event.wait_timer_in_secs = lte_interrat_redir_req.t_wait_time_ms / 1000;
  /*Copy the three byte MCC*/
  memscpy(td2l_redir_event.MCC,RRC_MAX_MCC_DIGITS*sizeof(byte), tdsrrc_csp_int_data.curr_req_plmn.plmn_id.mcc,RRC_MAX_MCC_DIGITS*sizeof(byte));
  /*Copy the three byte MNC*/
  memscpy(td2l_redir_event.MNC,RRC_MAX_MCC_DIGITS*sizeof(byte), tdsrrc_csp_int_data.curr_req_plmn.plmn_id.mnc,RRC_MAX_MCC_DIGITS*sizeof(byte));
  if(tdsrrc_csp_int_data.curr_req_plmn.plmn_id.num_mnc_digits == 2)
  {
    td2l_redir_event.MNC[2] = 0xF;
  }
  event_report_payload(EVENT_TDSCDMA_TO_LTE_REDIRECTION_START, sizeof(td2l_redir_event),
                 (void *)&td2l_redir_event);
}

