boolean tdsrrccsp_check_cgi_scan(void)
{
  if ((tdsrrc_csp_int_data.curr_scan == RRC_CSP_GSM_TO_TDS_CELL_RESELECTION_SCAN) 
     &&(tdsrrc_csp_int_data.interrat_type == TDSRRC_CSP_INTERRAT_LTE_CGI ))
  {
    return TRUE;
  }
  else
  {
    return FALSE;
  }
}


