/*===========================================================================
FUNCTION          tdsrrccsp_reselection_in_progress

DESCRIPTION       This function is responsible for returning the current 
                  status of Reselection in progress.
DEPENDENCIES
                  None

RETURN VALUE
                  A status that indicates if a Reselection is in progress
                  or not.
                  
SIDE EFFECTS      None
===========================================================================*/
boolean  tdsrrccsp_reselection_in_progress(void)
{
  tdsrrc_csp_substate_e_type curr_substate;

  curr_substate = tdsrrccsp_get_csp_substate();

  if ((curr_substate == TDSRRCCSP_SUIT_CELL_RESELECT_WT_SIB)||
      (curr_substate == TDSRRCCSP_ACCEPT_CELL_RESELECT_WT_SIB)||
      (curr_substate == TDSRRCCSP_SUIT_CELL_RESELECT_WT_CAMP)||
      (curr_substate == TDSRRCCSP_ACCEPT_CELL_RESELECT_WT_CAMP)||
      (curr_substate == TDSRRCCSP_SUIT_CELL_RESELECT_WT_SIB_PENDING)||
      (curr_substate == TDSRRCCSP_SUIT_CELL_RESELECT_WT_CAMP_PENDING)||
      (curr_substate == TDSRRCCSP_ACCEPT_CELL_RESELECT_WT_SIB_PENDING)||
      (curr_substate == TDSRRCCSP_ACCEPT_CELL_RESELECT_WT_CAMP_PENDING)||
      (curr_substate == TDSRRCCSP_SUIT_CELL_RESELECT_WT_TRANS_CNF)||
      (curr_substate == TDSRRCCSP_ACCEPT_CELL_RESELECT_WT_TRANS_CNF))
  {
    /* We are in cell reselection */
    return(TRUE);
  }
  else
  {
    /* Not in Cell Reselection at present */
    return(FALSE);
  }
}

/*=========================================================================

 FUNCTION     : tdsrrccsp_abort_cell_reselection
 
 DESCRIPTION  : This function aborts the cell reselection if any.
              
 DEPENDENCIES : None

 INPUT PARAMETERS : None

 RETURN VALUE : 
  TRUE - the reselection is absent or aborted successfully;
  FALSE - fail to abort the reselection;
       
 SIDE EFFECTS : 
   This function will update CSP substate and send commands to LLC.
==========================================================================*/
boolean tdsrrccsp_abort_cell_reselection(void)
{
  tdsrrc_csp_substate_e_type curr_substate;
  tdsrrc_csp_substate_e_type next_substate;
  boolean ret = FALSE;

  curr_substate = tdsrrccsp_get_csp_substate();

  if((curr_substate == TDSRRCCSP_SUIT_CELL_RESELECT_WT_SIB) ||
     (curr_substate == TDSRRCCSP_ACCEPT_CELL_RESELECT_WT_SIB))
  {
    if((tdsrrcllc_get_ordered_config_status() != TDSOC_SET_FOR_CELL_DCH) &&
       (tdsrrc_get_state() != TDSRRC_STATE_CELL_DCH))
    {
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"Aborting cell reselection"); 

      if(tdsrrcrce_is_call_pending() != TDSRRCRCE_NONE_CALL_PENDING)
      {
        /*tdsrrccsp_send_reselection_failure();*/
        tdsrrccsp_reselection_failure_ind_to_send = TRUE;
      }
      /* First Initialize the SIB variables */
      /* Signal SIB procedure to clear up the active event, if any */
      tdsrrcsib_force_sib_event_init(TDSRRCSIB_ABORT_DUE_TO_NGH_OOS);

      /* Send a TRANSITION_REQ to L1 with failure */
      tdsrrccsp_send_transition_failure();

      if(curr_substate == TDSRRCCSP_SUIT_CELL_RESELECT_WT_SIB)
      {
        next_substate = TDSRRCCSP_SUIT_CELL_RESELECT_WT_TRANS_CNF;
      }
      else
      {
        next_substate = TDSRRCCSP_ACCEPT_CELL_RESELECT_WT_TRANS_CNF;
      }

      /* Reset the reselection data */
      tdsrrccsp_reset_reselection_data();

      tdsrrccsp_substate = next_substate;

      ret = TRUE;
    }
    else
    {
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"Can't abort cell reselection - OC set for DCH"); 
    }
  }
  else
  {
    TDSRRC_MSG1(MSG_LEGACY_HIGH,"Can't abort cell reselection in csp_sstate %d",curr_substate); 
  }
  
  return ret;
}

