#ifdef FEATURE_DUAL_SIM
/*===========================================================================

FUNCTION        TDSRRC_FILL_SUB_ID_IN_IRAT_MSG

DESCRIPTION  This function adds TDS AS ID to the messages sent from TDSRRC to RR

DEPENDENCIES
                None

RETURN VALUE
                None

SIDE EFFECTS
                None

===========================================================================*/
static void tdsrrc_fill_sub_id_in_irat_msg(
  void *msg_ptr,
  tdsrr_rrc_cmd_e_type rrc_cmd_id,
  sys_modem_as_id_e_type as_id
)
{
  switch (rrc_cmd_id)
  {
    case TDSRR_INTERRAT_HANDOVER_REQ:
    {
      ((tdsrr_interrat_handover_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_HANDOVER_ABORT_REQ:
    {
      ((tdsrr_interrat_handover_abort_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_NAS_DATA_IND:
    {
      ((tdsrr_nas_data_ind_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_RESELECTION_REQ:
    {
      ((tdsrr_interrat_reselect_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_RESELECTION_ABORT_REQ:
    {
    ((tdsrr_interrat_reselection_abort_req_type *)msg_ptr)->as_id = as_id;
    break;
    }
    case TDSRR_INTERRAT_PLMN_SRCH_REQ:
    {
      ((tdsrr_interrat_plmn_srch_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_PLMN_SRCH_ABORT_REQ:
    {
      ((tdsrr_interrat_plmn_srch_abort_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_PLMN_SRCH_SUSPEND_IND:
    {
      ((tdsrr_interrat_plmn_srch_suspend_ind_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_CC_ORDER_REQ:
    {
      ((tdsrr_interrat_cc_order_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_CC_ORDER_ABORT_REQ:
    {
      ((tdsrr_interrat_cc_order_abort_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_REDIRECT_REQ:
    {
      ((tdsrr_interrat_redirect_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_REDIRECT_ABORT_REQ:
    {
      ((tdsrr_interrat_redirect_abort_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_STOP_GSM_REQ:
    {
      ((tdsrr_stop_gsm_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_INTERRAT_TL1_STOP_IND:
    {
      ((tdsrr_interrat_tl1_stop_ind_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_CIPHER_SYNC_IND:
    {
      ((tdsrr_cipher_sync_ind_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_INTERRAT_HANDOVER_CNF:
    {
      ((tdsrrc_interrat_handover_cnf_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_INTERRAT_HANDOVER_ABORT_CNF:
    {
      ((tdsrrc_interrat_handover_abort_cnf_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_INTERRAT_RESELECTION_REJ:
    {
      ((tdsrrc_interrat_reselect_rej_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_INTERRAT_RESELECTION_ABORT_CNF:
    {
      ((tdsrrc_interrat_reselection_abort_cnf_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_INTERRAT_PLMN_SRCH_CNF:
    {
      ((tdsrrc_interrat_plmn_srch_cnf_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_INTERRAT_PLMN_SRCH_ABORT_CNF:
    {
      ((tdsrrc_interrat_plmn_srch_abort_cnf_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_INTERRAT_REDIRECT_REJ:
    {
      ((tdsrrc_interrat_redirect_rej_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_INTERRAT_REDIRECT_ABORT_CNF:
    {
      ((tdsrrc_interrat_redirect_abort_cnf_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_STOP_TDS_CNF:
    {
      /* Skip AS_ID already assigned in tdsrrccsp_send_rrc_rr_stop_tds_cnf() */
      TDSRRC_MSG0(MSG_LEGACY_HIGH,"AS_ID for TDSRRC_STOP_TDS_CNF already assigned");
      break;
    }
    case TDSRR_DEDICATED_PRIORITIES_REQ:
    {
      ((tdsrr_dedicated_priorities_req_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRR_CLEAR_DEDICATED_PRIORITIES_IND:
    {
      ((tdsrr_clear_dedicated_priorities_ind_type *)msg_ptr)->as_id = as_id;
      break;
    }
    case TDSRRC_DEDICATED_PRIORITIES_RSP:
    {
      ((tdsrrc_dedicated_priorities_rsp_type *)msg_ptr)->as_id = as_id;
      break;
    }
    default:
    {
      TDSRRC_MSG1(MSG_LEGACY_ERROR,"Unknown TDSRRC->GRR msg (%d)",(int)rrc_cmd_id);
    }
  }
}
#endif // FEATURE_DUAL_SIM

/*===========================================================================

FUNCTION        TDSRR_SEND_RRC_MESSAGE_TO_RR_INTERNAL

DESCRIPTION     This function will add AS ID to the messages sent from RRC to RR
                and calls the function which actually sends the message

DEPENDENCIES
                None

RETURN VALUE
                None

SIDE EFFECTS
                None

===========================================================================*/

void tdsrr_send_rrc_message_to_rr_internal(
  void *            message_ptr,
  tdsrr_rrc_cmd_e_type rrc_cmd_id,
  word              length
)
{
#ifdef FEATURE_DUAL_SIM
  TDSRRC_MSG2(MSG_LEGACY_HIGH,"Fill AS-ID %d in irat msg %d",(int)(tdsrrc_get_as_id()),(int)rrc_cmd_id);
  tdsrrc_fill_sub_id_in_irat_msg(message_ptr, rrc_cmd_id, tdsrrc_get_as_id());
#endif  
  if(TDSCHECK_OPTIONAL_FEATURE_CFA_SUPPORTED)
  {
    tdscfa_tdsrr_send_rrc_message_to_rr(message_ptr, rrc_cmd_id, length );
  }
  tdsrr_send_rrc_message_to_rr(message_ptr, rrc_cmd_id, length );
  return;
}

