/*===========================================================================

FUNCTION        tdsrrccsp_get_system_time

DESCRIPTION     This function will return the current system time

DEPENDENCIES
                None

RETURN VALUE
                uint32

SIDE EFFECTS
                None

===========================================================================*/
uint32 tdsrrccsp_get_system_time(void)
{
  time_type up_ms;
  uint32 lo32;
  time_get_uptime_ms(up_ms);
  lo32 = qw_lo(up_ms);

  TDSRRC_MSG3(MSG_LEGACY_HIGH,"TDSRRCCSP:System time %d", lo32, 0, 0);
  return lo32;
}

/*===========================================================================

FUNCTION  tdsrrcdsds_check_for_auto_bplmn_srch_priority

DESCRIPTION

  This function check bplmn_drx_cnt and determain which activity should be update 
  to TDRM before T2T/X auto BPLMN search.

  T2T/X Auto BPLMN
  bplmn_drx_cnt mod 5 != 0   update " TRM_ACQUISITION_CELL_SELECT"
  bplmn_drx_cnt mod 5 == 0   update " TRM_ACQUISITION_CELL_SELECT_INV "
  
DEPENDENCIES

  None.
 
RETURN VALUE

  lock priority 

SIDE EFFECTS

  None.

===========================================================================*/
trm_reason_enum_t tdsrrcdsds_check_for_auto_bplmn_srch_priority()
{
  if (tdsrrc_csp_int_data.bplmn_drx_cnt%5 != 0)
  {
    return TRM_ACQUISITION_CELL_SELECT;
  }
  else
  {
    return TRM_ACQUISITION_CELL_SELECT_INV;
  }
}

/*===========================================================================

FUNCTION  tdsrrcdsds_check_for_manual_bplmn_srch_priority

DESCRIPTION

  This function check bplmn_drx_cnt and determain which activity should be update 
  to TDRM before T2T/X manual BPLMN search.

  T2T/X Manual BPLMN
  bplmn_drx_cnt mod 5 != 0   update " TRM_ACQUISITION_CELL_SELECT_INV "
  bplmn_drx_cnt mod 5 == 0   update " TRM_ACQUISITION_CELL_SELECT"

DEPENDENCIES

  None.
 
RETURN VALUE

  lock priority 

SIDE EFFECTS

  None.

===========================================================================*/
trm_reason_enum_t tdsrrcdsds_check_for_manual_bplmn_srch_priority()
{
  if (tdsrrc_csp_int_data.bplmn_drx_cnt%5 != 0)
  {
    return TRM_ACQUISITION_CELL_SELECT_INV;
  }
  else
  {
    return TRM_ACQUISITION_CELL_SELECT;
  }
}

